INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (1, 'seed', 'patent_manual', '制汗剤組成物', '本発明に係る制汗剤組成物は、特定の量のグリチルリチン酸アンモニウムを含有する。', 'ヒトの汗腺は主に汗の分泌により体温調節を行う重要な器官であるが、体温調節に不必要なほどの多量の汗、微生物が汗を分解した代謝物の臭いおよび酸化で生じる臭いは不快感を与え得る。従来の制汗剤は塩化アルミニウム等の金属イオンで汗孔を閉塞させる物理的な制汗作用が中心だった。特許文献1（特開昭52-105221）にグリチルリチン酸の制汗効果が報告されていたが、効果は十分でなかった。', '汗孔を閉塞させなくとも、汗腺に作用して汗の分泌を制御できる制汗剤組成物を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2021-046382/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (2, 'seed', 'patent_manual', '発汗調整方法、発汗調整剤および発汗調整剤のスクリーニング方法', 'TRPV1、TRPV3およびTRPM4からなる群より選択される少なくとも1種のTRPチャネルの活性調整剤を用いる。', '汗腺はアポクリン汗腺とエクリン汗腺の2種類。温熱性発汗は大脳視床下部が体温上昇を感知しアセチルコリン分泌→汗腺のムスカリン受容体結合で発汗する機序が知られていたが、ヒトの汗腺研究は立ち遅れており、発汗調整が末梢神経系で行われるか不明だった。', '発汗調整方法、発汗調整剤、および、発汗調整剤のスクリーニング方法を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2025-025004/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (3, 'seed', 'patent_manual', 'サイトカイン産生抑制剤', 'TRPM4を活性化して皮膚細胞におけるサイトカイン産生を抑制する用途に用いられるサイトカイン産生抑制剤であって、有効成分としてアルミニウム化合物（制汗成分として既知）を含有する。', '皮膚の炎症はニキビ痕・シミ・シワの原因となる。既存の抗炎症剤は発生した炎症を鎮静化するもので、炎症の原因因子であるサイトカイン産生自体を抑制する炎症予防剤の開発が望まれていた。', '被験試料が皮膚細胞におけるサイトカイン産生を抑制する作用を有するかどうかを容易に評価する方法、および効果的なサイトカイン産生抑制剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2022-068272/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (4, 'seed', 'patent_manual', 'TRPV1活性抑制剤、および、その利用', 'ルペオール、グアイアズレン、トングハオス、これらの誘導体および誘導体の塩からなる群より選択される少なくとも1種を有効成分として含有する。', 'TRPV1はカプサイシンや熱に感受性を持つイオンチャネルで、活性化は炎症性疼痛と関連する。既知のTRPV1抑制物質（メントール、メントキシプロパンジオール等）はTRPM8の活性促進作用も併せ持つため肌に清涼感を与えてしまい、清涼感の付与が不要な製剤には使いにくいという課題があった。', '新規なTRPV1活性抑制剤、および、その利用を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2025-137454/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (5, 'seed', 'patent_manual', 'TRPA1の活性抑制剤および活性抑制方法ならびに皮膚外用剤', '炭酸イオンおよび／または炭酸水素イオンを含有するTRPA1の活性抑制剤。', 'パラベン類やアルカリ剤を配合した化粧料は皮膚に不快な刺激を感じることがあり、この刺激はTRPA1の活性化と関連することが発明者らにより見出されていた。安全意識の高まりから刺激の少ない外用剤が求められていた。', 'TRPA1の活性化を効果的に抑制する活性抑制剤・方法、および皮膚刺激性が低い皮膚外用剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2011-140471/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (6, 'seed', 'patent_manual', 'TRPV1活性抑制剤、およびその利用', 'メントキシプロパンジオール、メントングリセリンアセタール、乳酸メンチル、およびこれらの塩からなる群から選ばれる少なくとも1種を有効成分として含有する。', 'TRPV1はカプサイシン・熱に感受性を有し、活性化は炎症性疼痛と関連する。既知のTRPV1活性抑制剤としてメントールが知られていたが、メントール以外の候補物質の開発が求められていた。', '新規のTRPV1活性抑制剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2022-144971/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (7, 'seed', 'patent_manual', '清涼感持続性化粧料', 'アルコール、清涼成分およびポリオキシエチレンアルキルエーテルを含有する清涼感持続性化粧料であって、前記ポリオキシエチレンアルキルエーテルが分岐アルキル基を有するポリオキシエチレンアルキルエーテルであることを特徴とする。噴射剤を加えたエアゾール組成物としても提供する。', '冷感を与える化粧料には、低級アルコールや揮発性ガスの気化熱で実際に皮膚表面温度を下げるタイプと、メントール等の清涼成分で感覚的に冷感を与えるタイプがある。後者は清涼成分の含有率で清涼感の強さ・持続性を制御するが、強くしようと含有率を上げると痛み・灼熱感などの不快感が生じ、逆に抑えると持続しないというトレードオフがあった。', '皮膚に対して清涼感を与えるとともにその清涼感の持続性に優れた清涼感持続性化粧料を提供すること。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2012-087108/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (8, 'seed', 'patent_manual', '冷感付与組成物', 'l-メンチルグリセリルエーテルを6.0〜40質量%、低級アルコールを5.0〜90質量%含有する。', 'マスク着用時は呼吸がしにくく、呼気や汗でマスク内が蒸れて不快度が高くなる（熱中症リスクも）。接触冷感マスクや衣類用冷感付与組成物が知られていたが、着用直後は冷感があっても持続性が不十分で、エタノール・l-メントールの配合量が多いため皮膚・眼への刺激が懸念されていた。', '冷感および冷感の持続性に優れ、皮膚刺激および眼刺激が低減された冷感付与組成物を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2022-052528/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (9, 'seed', 'patent_manual', '体臭抑制剤', 'クスノハガシワ抽出物およびキナ抽出物からなる群より選ばれた少なくとも1種の抽出物を含有する。', '体臭は腋窩部・頭部等の複数の臭いが混じったもの。腋臭原因物質は3-メチル-2-ヘキセン酸等の短鎖脂肪酸やアンドロステノン類。既存デオドラント剤（オウバク抽出物等）では腋窩部の酸臭・頭部のアブラ臭を十分抑制できていなかった。', '体臭、特に腋窩部の酸臭を抑制する体臭抑制剤、および皮膚成分由来のジケトン化合物の作用を抑制するジケトン作用抑制剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2016-033158/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (10, 'seed', 'patent_manual', 'ジケトン作用抑制剤', 'シモツケソウ抽出物、ヒマラヤンラズベリー抽出物、ボダイジュ抽出物およびバラ抽出物からなる群より選ばれた少なくとも1種の抽出物を含有する。', '腋臭・頭部臭の原因物質と既存デオドラント剤の限界（特開2016-033158と同様の背景）。皮膚上のジケトン化合物の生成と体臭との関連性を具体的に記載した文献は当時発見されていなかった。', 'ジケトン化合物の作用を抑制するジケトン作用抑制剤、および腋窩部の酸臭・頭部のアブラ臭を抑制する体臭抑制剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2014-028778/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (11, 'seed', 'patent_manual', '体臭抑制剤', 'アスコルビン酸脂肪酸エステル化合物を含有する。', '腋臭・頭部臭の原因物質と既存デオドラント剤の限界（特開2016-033158・特開2014-028778と共通の背景）。', '腋窩部の酸臭・頭部のアブラ臭を抑制する体臭抑制剤、およびジケトン作用抑制剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2014-055124/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (12, 'seed', 'patent_manual', '体臭抑制剤組成物', 'ラウリルジアミノエチルグリシンナトリウムを含有する。', '30〜50才の男性特有の脂っぽい汗の臭い（ミドル脂臭）はジアセチルと短鎖・中鎖脂肪酸が原因。短鎖・中鎖脂肪酸は皮脂臭にも関係する。従来はポリヒドロキシアミン化合物による化学的中和消臭が知られていたが、より強い効果が求められていた。', '体臭を効果的に抑制することが可能な体臭抑制剤組成物の提供を目的とする。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2023-137513/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (13, 'seed', 'patent_manual', '皮脂臭抑制剤組成物', '成分(A)トリスヒドロキシメチルアミノメタンおよび2-アミノ-2-メチル-1,3-プロパンジオールからなる群より選択される少なくとも1つのポリヒドロキシアミン化合物と、成分(B)ラウロアンホ酢酸ナトリウムを含有する。', 'ミドル脂臭＝ジアセチル＋短鎖・中鎖脂肪酸、皮脂臭との関係（特開2023-137513と共通の背景）。', 'ミドル脂臭（特に皮脂臭）を効果的に抑制する皮脂臭抑制剤組成物を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2022-151660/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (14, 'seed', 'patent_manual', '腋臭菌用抗菌剤、並びに該抗菌剤を含有する腋臭防止剤及び皮膚外用剤', '(A)2-メチル-4-イソチアゾリン-3-オンおよび／または5-クロロ-2-メチル-4-イソチアゾリン-3-オンと、(B)メントール、メンチルグリセリルエーテルおよびカンファーからなる群から選ばれる1種以上を含有する。', '腋臭は汗と皮脂がコリネバクテリウム属菌等により分解され悪臭物質を生成することで発生。既存の体臭防止薬剤（アルミニウム塩の制汗剤、トリクロサン等の殺菌剤、酸化亜鉛等の消臭剤）はそれぞれ皮膚刺激性・皮脂での抗菌力低下・臭いの根本解決にならないという問題があった。', 'メントール等の冷感剤を4-イソチアゾリン-3-オン化合物と共に用いることで、従来の体臭防止用薬剤なしに腋臭原因菌への抗菌力を相乗的に増強すること。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2007-186465/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (15, 'seed', 'patent_manual', '腋臭原因菌用抗菌剤、並びに該抗菌剤を含有する腋臭防止剤', '炭素数5〜10の1,2-アルカンジオールと、α-ビサボロールとを含有する（1,2-ヘキサンジオールまたは1,2-オクタンジオールが好ましい）。', '腋臭は汗と皮脂がコリネバクテリウム属菌等により分解され悪臭物質を生成することで発生（特開2007-186465と共通の背景）。先行文献で1,2-アルカンジオール単体やα-ビサボロール単体の抗菌性・保湿性は個別に報告されていたが、両者の組み合わせによる腋臭原因菌への相乗的抗菌効果は報告されていなかった。', '従来の制汗剤・殺菌剤・消臭剤等を用いなくとも、腋臭原因菌への抗菌力が相乗的に増強された抗菌剤・腋臭防止剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2009-046442/11/ja', NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (16, 'need', 'faq', 'シャンプーしてもワックスが落ちない', 'シャンプーしてもヘアワックスが落ちない。', NULL, NULL, 'https://www.mandom.co.jp/customer/faq_detail.html?id=78', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (17, 'need', 'dummy', '洗い流しやすい整髪料の企画', 'セット力はそのままに、お風呂で簡単に洗い流せる整髪料を企画したい。毎日使うものなので、髪や頭皮への負担が少ない処方を探している。', NULL, NULL, NULL, NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (18, 'need', 'dummy', '制汗しても夕方に臭いが戻る', '朝しっかり制汗スプレーをしたのに、夕方になるとまた汗臭さが気になる。制汗効果がもっと長く続いてほしい。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (19, 'need', 'dummy', '汗で肌がベタつく不快感', '汗をかくと肌がベタベタして不快。サラサラした状態を保てる商品がほしい。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (20, 'need', 'dummy', '制汗剤を塗るとピリピリする', '汗を抑えるタイプの商品を脇に塗ると、ピリピリした刺激を感じることがあって続けにくい。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (21, 'need', 'dummy', '暑い日の化粧水の冷たさが続かない', '夏に化粧水をつけた直後はひんやり気持ちいいけど、そのひんやり感がすぐになくなってしまう。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (22, 'need', 'dummy', 'マスクが蒸れて息苦しい', 'マスクをしていると呼気と汗で中が蒸れて、苦しく感じることがある。涼しさが続くマスクグッズがあれば知りたい。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (23, 'need', 'dummy', '頭皮のベタつき・ニオイが気になる', '一日過ごすと頭皮がベタついて、頭のニオイも気になるようになる。何が原因なのか知りたい。', NULL, NULL, NULL, NULL, 'ボディケア', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (24, 'seed', 'patent_manual', '整髪剤組成物（α-ケトグルタル酸）', '本発明の整髪剤組成物は、成分（A）：α−ケトグルタル酸、並びに成分（B）：水及び／又はエタノールを含有し、前記成分（A）の含有割合が0.01〜0.8質量％であり、pHが6.8以下である。', NULL, 'α−ケトグルタル酸を整髪成分として用いた整髪剤組成物を提供する。また、整髪後の髪型の耐湿性に優れる整髪剤組成物を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2020-158482/11/ja', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (25, 'seed', 'patent_manual', 'エアゾールスプレー整髪剤（シリカ）', '所定量のエアゾールスプレー整髪剤組成物と噴射剤とから構成され、成分X：平均粒子径が5〜18μmのシリカ、成分Y：エステル油及び炭化水素油からなる群から選ばれる少なくとも1種の油剤を含有する。', NULL, 'シリカを整髪成分として含有し、充分な整髪力及び整髪後の再整髪力を有するエアゾールスプレー整髪剤であり、噴射物の舞い散りが少なく、付着率に優れ、粉浮きが少なく、さらに速乾性に優れたエアゾールスプレー整髪剤を提供すること。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2018-154571/11/ja', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (26, 'seed', 'patent_manual', '整髪剤用アクリル系樹脂エマルション', 'ガラス転移温度が−15℃以上かつ0℃未満であるアクリル系樹脂エマルション［I］、ガラス転移温度が0℃以上かつ60℃以下であるアクリル系樹脂エマルション［II］、および無機粒子を含有する整髪剤用アクリル系樹脂エマルションとする。', NULL, '整髪性能（立ち上げ力、毛束感）に優れ、ベタツキが少なく、かつ、フレーキングが非常に少ない整髪剤用アクリル系樹脂エマルションおよびこれを用いた整髪剤を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2017-160166/11/ja', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (27, 'seed', 'patent_manual', '頭髪用セット剤組成物', '（A）アクリル樹脂アルカノールアミンと、（B）N−メタクリロイルオキシエチルN,N−ジメチルアンモニウム−α−N−メチルカルボキシベタイン・メタクリル酸アルキルエステル共重合体、ポリビニルピロリドン及びビニルピロリドン・N,N−ジメチルアミノエチルメタクリル酸共重合体からなる群から選ばれる1種以上と、（C）水とを含有する頭髪用セット剤組成物。', NULL, 'アクリル樹脂アルカノールアミンと、特定の高分子樹脂化合物を併用することにより、高分子樹脂化合物が本来有するセット力を更に向上させると共に、ごわつきやフレーキングと言ったスタイリング剤特有の問題を低減した整髪用セット剤組成物の提供。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2006-069904/11/ja', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO documents (id, doc_type, source, title, body, background, problem, url, pub_date, category, dept, summary_plain, parent_id, chunk_no, content_hash, fetched_at) VALUES (28, 'seed', 'patent_manual', '非乳化型固形状整髪剤組成物（洗い流しやすい）', '脂肪酸塩（成分A）と、皮膜形成ポリマー（成分B）と、水（成分C）とを含み、成分Aの含有量が2.0質量％以上13.0質量％以下、成分Bの含有量が2.0質量％以上10.0質量％以下、成分Cの含有量が20.0質量％以上95.0質量％以下である。', NULL, '塗布性及び整髪力に優れ、かつ洗髪時に容易に洗い流すことができる固形状整髪剤組成物を提供する。', 'https://www.j-platpat.inpit.go.jp/c1801/PU/JP-2020-152643/11/ja', NULL, 'ヘアスタイリング', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO projects (id, name, brief, category, status, started, is_sample) VALUES (1, 'ふわさら吸汗ボディシート', '汗の分泌そのものを抑える処方で、長時間のサラサラ感を訴求するデオドラントシート企画', 'ボディケア', 'launched', '2025-11-01', 1);
INSERT INTO projects (id, name, brief, category, status, started, is_sample) VALUES (2, 'アイスクリアタッチ化粧水', 'つけた瞬間だけでなく清涼感の持続性を訴求する夏季限定化粧水企画', 'フェイスケア', 'launched', '2026-01-10', 1);
INSERT INTO projects (id, name, brief, category, status, started, is_sample) VALUES (3, '洗い流しやすい固形スタイリングワックス', 'セット力を保ちながら入浴時に簡単に洗い流せることを訴求するワックス企画', 'ヘアスタイリング', 'ongoing', '2026-07-01', 1);
INSERT INTO projects (id, name, brief, category, status, started, is_sample) VALUES (4, '速乾ミストスタイリング', '速乾性と舞い散りの少なさを両立したミストタイプのスタイリング剤企画', 'ヘアスタイリング', 'launched', '2026-05-01', 1);
INSERT INTO projects (id, name, brief, category, status, started, is_sample) VALUES (5, '敏感肌向けやさしい整髪ライン', '低刺激処方を訴求する整髪剤ライン企画', 'ヘアスタイリング', 'cancelled', '2026-03-01', 1);
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (1, 1, 1, 'adopted', '汗腺に作用して分泌自体を抑える点が「長時間サラサラ」の訴求に直結するため採用', '社内官能評価で8時間後のベタつき感が従来品比で改善', '2025-10-20');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (2, 1, 3, 'evaluating', '抗炎症効果を追加訴求できないか処方検証中', 'パッチテストの結果待ち', '2025-10-25');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (3, 2, 7, 'adopted', '清涼感の持続性がコンセプトと直結するため採用', '官能評価で使用1時間後も清涼感を確認', '2025-12-15');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (4, 2, 6, 'dropped', '原料コストが想定の3倍となり、処方への置き換えを断念', '代替サプライヤーも検討したが価格が折り合わなかった', '2025-12-20');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (5, 3, 28, 'adopted', '洗髪時に容易に洗い流せる点が「洗い流しやすさ」の企画コンセプトと直結するため採用', '試作品の官能評価で好感触。量産化に向けて処方調整中', '2026-07-10');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (6, 3, 26, 'dropped', 'セット力は高いが洗い流しにくく、今回の「洗い流しやすさ」の要件と相反するため不採用', 'シャンプー1回では落ちきらないことを確認', '2026-07-12');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (7, 3, 27, 'dropped', 'セット力はあるが洗浄性が低く、要件を満たさないため不採用', '過去の別企画でも同じ理由で見送った実績あり', '2026-07-11');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (8, 4, 25, 'adopted', '速乾性と舞い散りの少なさがミスト処方の課題解決に直結するため採用', '乾燥時間を従来品比で約30%短縮', '2026-05-10');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (9, 4, 26, 'adopted', '立ち上げ力を補強するため併用採用', 'セット力評価で改善を確認', '2026-05-12');
INSERT INTO project_techs (id, project_id, seed_id, decision, reason, detail, decided_at) VALUES (10, 5, 24, 'evaluating', '低刺激性の確認のため処方検証中だったが、企画自体の中止により判断は保留のまま', 'パッチテストは実施中だった', '2026-03-10');
